insert into public.startups (name, slug, description) values
('AeroQ', 'aeroq', 'Building smarter tools for aviation operations.'),
('Sadeem Technology', 'sadeem-technology', 'Environmental intelligence and connected sensing.'),
('GreenRoute', 'greenroute', 'Technology for more sustainable mobility.'),
('MedLoop', 'medloop', 'Digital health products for connected care.')
on conflict (slug) do update set name = excluded.name, description = excluded.description;

insert into public.jobs (startup_id, title, slug, department, location, employment_type, work_arrangement, deadline, openings, description, qualifications, requirements, status, published_at)
